SELECT if(isNull(_num_value) OR isNull(_den_value) OR _den_value = 0, NULL, _num_value / _den_value) AS value, _dim_0 FROM (SELECT value AS _num_value, _dim_0 FROM (SELECT count() AS value, _dim_0 FROM (SELECT NULL AS _metric_value, attributes['route'] AS _dim_0 FROM posthog.trace_spans WHERE service_name = 'arena' AND timestamp >= now() - INTERVAL 3600 SECOND AND (attributes['target'] = 'cja::server::trace' AND attributes['kind'] = 'server')) AS _source WHERE (SELECT count() FROM (SELECT 1 FROM posthog.trace_spans WHERE service_name = 'arena' AND timestamp <= now() - INTERVAL 3600 SECOND LIMIT 1)) > 0 GROUP BY _dim_0 ORDER BY _dim_0 LIMIT 50000) AS _num_rows) AS _num CROSS JOIN (SELECT value AS _den_value FROM (SELECT if((SELECT count() FROM (SELECT 1 FROM posthog.trace_spans WHERE service_name = 'arena' AND timestamp <= now() - INTERVAL 3600 SECOND LIMIT 1)) > 0, count(), NULL) AS value FROM (SELECT NULL AS _metric_value FROM posthog.trace_spans WHERE service_name = 'arena' AND timestamp >= now() - INTERVAL 3600 SECOND AND (attributes['target'] = 'cja::server::trace' AND attributes['kind'] = 'server')) AS _source LIMIT 1) LIMIT 1) AS _den ORDER BY _dim_0 LIMIT 50000
